('q_chem-latky-smesi_0','Co zkoumá chemie?',ARRAY['Stavbu živých organismů','Vznik a vývoj Země','Pohyb těles a sílu','Látky, jejich vlastnosti a přeměny']::TEXT[],3,'Chemie je věda o látkách a jejich přeměnách.',1,ARRAY[]::TEXT[],NULL,0,'c_chem-latky-smesi',NULL,NOW()),
